{
  "narratives": [
    {
      "item_code": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "start":  "p3:L4",
      "end":    "p3:L9"
    },
    {
      "item_code": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "start":  "p3:L10",
      "end":    "p3:L17"
    },
    {
      "item_code": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "start":  "p3:L18",
      "end":    "p3:L22"
    },
    {
      "item_code": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "start":  "p3:L23",
      "end":    "p3:L27"
    },
    {
      "item_code": "S4_DOCTOR",
      "title_raw": "마. 기타 의사의 주의사항",
      "start":  "p3:L28",
      "end":    "p3:L30"
    }
  ]
  ,
  "extras": [
    {
      "after_item": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "reason": "필드없음",
      "statements": [
        {
          "value": "눈을 문지르지 마시오."
        ,
          "line": "p3:L5"
        },
        {
          "value": "많은 양의 물을 사용하여 적어도 15분 동안 눈을 씻어내시오."
        ,
          "line": "p3:L6"
        },
        {
          "value": "즉시 의사의 치료를 받으시오."
        ,
          "line": "p3:L7"
        },
        {
          "value": "증상(발적, 자극 등)이 발생할 경우 즉시 병원으로 가시오."
        ,
          "line": "p3:L8"
        },
        {
          "value": "콘택트렌즈를 착용했을 경우 우선 렌즈를 제거하시오."
        ,
          "line": "p3:L9"
        }
      ]
    ,
      "suggested_code": "S4_EYE"
    ,
      "line": "p3:L4"
    },
    {
      "after_item": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "reason": "필드없음",
      "statements": [
        {
          "value": "오염된 의복 및 신발을 벗고 즉시 적어도 15분 동안 비누와 물로 씻어내시오."
        ,
          "line": "p3:L11"
        },
        {
          "value": "오염된 피복은 재사용 전에 (충분히) 세탁하시오"
        ,
          "line": "p3:L12"
        },
        {
          "value": "오염된 피복과 신발을 제거하고 격리시키시오."
        ,
          "line": "p3:L13"
        },
        {
          "value": "즉시 의사의 치료를 받으시오."
        ,
          "line": "p3:L14"
        },
        {
          "value": "증상(발적, 자극 등)이 발생할 경우 즉시 병원으로 가시오."
        ,
          "line": "p3:L15"
        },
        {
          "value": "취급 후 철저히 씻으시오."
        ,
          "line": "p3:L16"
        },
        {
          "value": "환자를 씻길 경우 장갑을 착용하고 오염된 피복의 접촉을 피하시오."
        ,
          "line": "p3:L17"
        }
      ]
    ,
      "suggested_code": "S4_SKIN"
    ,
      "line": "p3:L10"
    },
    {
      "after_item": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "reason": "필드없음",
      "statements": [
        {
          "value": "다량의 증기나 미스트에 노출되었을 경우 맑은 공기가 있는 곳으로 이동하시오."
        ,
          "line": "p3:L19"
        },
        {
          "value": "필요에 따른 조치를 취하시오."
        ,
          "line": "p3:L20"
        },
        {
          "value": "즉시 의사의 치료를 받으시오."
        ,
          "line": "p3:L21"
        },
        {
          "value": "호흡이 불규칙하거나 멈출 경우 인공호흡을 실시하고 산소를 공급하시오."
        ,
          "line": "p3:L22"
        }
      ]
    ,
      "suggested_code": "S4_INHAL"
    ,
      "line": "p3:L18"
    },
    {
      "after_item": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "reason": "필드없음",
      "statements": [
        {
          "value": "구토를 유발해야 하는지에 대해서 의사의 조언을 받으시오."
        ,
          "line": "p3:L24"
        },
        {
          "value": "즉시 물로 입을 씻어내시오."
        ,
          "line": "p3:L25"
        },
        {
          "value": "만약 삼켰다면 많은 양의 물을 마시도록하고 구토를 유도하지 마시오."
        ,
          "line": "p3:L26"
        },
        {
          "value": "즉시 의사의 치료를 받으시오."
        ,
          "line": "p3:L27"
        }
      ]
    ,
      "suggested_code": "S4_INGEST"
    ,
      "line": "p3:L23"
    },
    {
      "after_item": "S4_DOCTOR",
      "title_raw": "마. 기타 의사의 주의사항",
      "reason": "필드없음",
      "statements": [
        {
          "value": "오염상황을 의료관계자에게 알려 그들도 적절한 보호조치를 취하도록 하시오."
        ,
          "line": "p3:L29"
        },
        {
          "value": "노출 및 노출 우려시 의학적인 조치, 조언을 구하시오."
        ,
          "line": "p3:L30"
        }
      ]
    ,
      "suggested_code": "S4_DOCTOR"
    ,
      "line": "p3:L28"
    }
  ]
}

